# 判定「改动是否发生在本次检查窗口内」时容忍的文件系统时间戳粒度（纳秒）。
# 见 `_diff_snap()` 的说明：不留容差会让自检**随机变红**（实测 4 次跑里 1 次 FAIL）。
_MTIME_GRACE_NS = 1_000_000_000


def _sha(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def _snapshot():
    """工作区快照：{绝对路径: (st_mtime_ns, st_size)}。

    只记 (mtime, size)，不算哈希——理由见 `_WATCH_DIRS` 上方注释（实测 892 文件
    SHA 0.1 s/趟 × 116 趟 ≈ 12 s，且随 wiki 增长线性上升）。
    """
    snap = {}
    for d in _WATCH_DIRS:
        base = d if os.path.isabs(d) else os.path.join(VAULT, d)
        if os.path.isfile(base):
            targets = [base]
        else:
            targets = [p for p in glob.glob(os.path.join(base, "**", "*"),
                                            recursive=True) if os.path.isfile(p)]
        for fp in targets:
            rel = _rel(fp).replace("\\", "/")
            # 排除派生数据（wiki/.index）与字节码：前者会大面积 churn（判据会退化成
            # 「谁跑了索引谁就红」），后者是解释器噪声、与工具行为无关。
            if fp.endswith(".pyc") or any(rel == x or rel.startswith(x + "/")
                                          for x in _WATCH_EXCLUDE):
                continue
            try:
                st = os.stat(fp)
            except OSError:
                continue
            snap[fp] = (st.st_mtime_ns, st.st_size)
    return snap


def _rel(p):
    try:
        # 统一成正斜杠：报告与夹具判据都用 `wiki/x.md` 这种形式比对。
        # 直接用 os.path.relpath 会在 Windows 下给出 `wiki\\x.md`，于是
        # 「同一路径」在报告里出现两种写法、夹具里的字符串比对也会失配
        # （实测：external 返回 `wiki\\stale.md`，而断言查的是 `wiki/stale.md`）。
        return os.path.relpath(p, VAULT).replace("\\", "/")
    except ValueError:
        return p


def _diff_snap(a, b, since=None):
    """比对两次快照。

    since（纳秒级起始时刻）给出时，**只把「改动发生在本次检查窗口内」的条目算作
    意外写盘**；窗口之前就已存在的差异单独返回为 external。

    🔴 为什么必须这么分流：本库的 Lead 与多个 subagent **会并发编辑 tools/ 与 wiki/**。
    快照只覆盖「工具运行前后」，一次外部编辑就会让**当时正在被检查的那个工具**平白
    被判 WRITES（实测窗口内确有 tools/*.py 被并发改写）。不加分流，扩大监视范围就直接
    等于把真判据淹没在外部噪声里——那比不扩围更糟（会诱使人把真发现也当噪声忽略）。
    mtime 早于窗口起点的改动**不可能**是本窗口内的工具所为，故归入 external 并单独报出
    （不隐藏：若 external 突然很多，说明工作区正被别的进程写，本次写盘判据可信度下降）。
    """
    changed, added, removed, external = [], [], [], []
    # 🔴 `_MTIME_GRACE_NS`：**容忍文件系统时间戳粒度**。
    #    判据是 `mtime < since` ⇒ 归入 external。但 `st_mtime_ns` 的分辨率并不总是 1 ns：
    #    NTFS 常见 100 ns～1 ms，FAT/SMB 共享可粗到 2 s。若某工具在窗口开始时**同一时钟滴答内**
    #    写盘，它写出的 mtime 可能比 `since` 早几微秒 ⇒ 被误判成 external ⇒ 该工具平白变绿。
    #    这正是 2026-10-10 实测到的**自检闪断**：同一份自检跑 4 次，3 次 PASS、1 次 FAIL
    #    （`反例 窗口内的写入仍被判红` 报 changed=0 external=1）。
    #    「随机变红的门禁」比没有门禁更糟——它会训练人把真发现也当噪声忽略（本库反复记过这一点）。
    #    故留 1 秒容差：窗口外部的并发编辑通常发生在**数秒/数分钟**前，1 秒不会把它们放进来。
    changed, added, removed, external = [], [], [], []
    for p in a:
        if p in b and a[p] != b[p]:
            (external if (since is not None and b[p][0] < since - _MTIME_GRACE_NS)
             else changed).append(_rel(p))
    for p in b:
        if p not in a:
            (external if (since is not None and b[p][0] < since - _MTIME_GRACE_NS)
             else added).append(_rel(p))
    for p in a:
        if p not in b:
            # 删除无法用「新文件的 mtime」判断窗口归属，故一律计入（删除比新建罕见得多，
            # 且本库纪律是「只移不删」，真出现删除本就该被看见）。
            removed.append(_rel(p))
    return (sorted(set(changed)), sorted(set(added)), sorted(set(removed)),
            sorted(set(external)))


def _now_ns():
    """单调递增的纳秒时刻，用于划出「本次检查窗口」。

    用 time.time_ns() 而不是 perf_counter：StructuredFile 的 st_mtime_ns 与它同源，
    两者可直接比较；perf_counter 的基准点与文件时间戳不同源，比较无意义。
    """
    return time.time_ns()


def _run(args, cwd=VAULT):
    # 🔴 子进程强制 utf-8：本机 Python 默认按 GBK 编码 stdout，若被检查脚本的
    #    selftest/--help 输出含 ⊂/⇒ 等非 GBK 字符，会抛 UnicodeEncodeError，
    #    被误判为「工具损坏」（kb_build_index / qc_unwrap_author_links 曾各中一次）。
    #    PYTHONIOENCODING 经 env 透传，且对脚本内部 subprocess 调用亦生效。
    env = dict(os.environ, PYTHONIOENCODING="utf-8")
    try:
        r = subprocess.run(args, capture_output=True, timeout=TIMEOUT, text=True,
                           encoding="utf-8", errors="replace", cwd=cwd, env=env)
        return r.returncode, (r.stdout or "") + (r.stderr or "")
    except subprocess.TimeoutExpired:
        return None, "TIMEOUT"
    except Exception as e:  # noqa
        return -1, f"EXEC-ERROR: {e}"


def _last_line(s, n=70):
    ls = [x.strip() for x in (s or "").splitlines() if x.strip()]
    return ls[-1][:n] if ls else ""


def _guard(pre, since, label, rec):
    """比对快照并把结果写进 rec。区分「意外写盘」与「窗口外的并发外部编辑」。

    返回 (changed, added, removed, external) 供调用方汇总。
    """
    ch, ad, rm, ex = _diff_snap(pre, _snapshot(), since=since)
    if ch or ad or rm:
        rec["write_guard"] = "WRITES"
        rec["notes"].append(
            f"{label} 意外改动工作区: 改{len(ch)} 增{len(ad)} 删{len(rm)}"
            + (f"  样例={((ch + ad + rm)[:3])}" if (ch or ad or rm) else ""))
    if ex:
        # 不判红：这些差异的 mtime 早于本次窗口起点，**不可能**是本窗口内的工具所为
        # （本库 Lead/多个 subagent 会并发编辑 tools/、wiki/）。但也不静默丢弃——
        # 报出来，让读报告的人知道这次判据的可信度。
        rec["external_writes"] = ex
        rec["notes"].append(f"{label} 窗口外并发改动 {len(ex)} 个文件（不计入判定）")
    return ch, ad, rm, ex


def check_one(name, path, do_write_guard=True):
    """返回 dict：{name, compile, selftest, help, write_guard, notes[], external_writes}"""
    rec = {"name": name, "compile": None, "selftest": None,
           "help": None, "write_guard": None, "external_writes": [], "notes": []}

    # --- B 编译健全性 ---
    rc, out = _run([PY, "-c", f"import py_compile,sys; py_compile.compile({path!r}, doraise=True)"])
    rec["compile"] = "ok" if rc == 0 else "FAIL"
    if rc != 0:
        rec["notes"].append("compile: " + _last_line(out))
        return rec  # 编译都不过，后面无意义

    src = open(path, encoding="utf-8", errors="replace").read()
    has_st = "--selftest" in src or "selftest" in src

    # --- S 自检可用性（实跑） ---
    if has_st:
        # 窗口起点必须在被测工具**启动之前**取：mtime 落在窗口内的改动才可能是它写的。
        since = _now_ns()
        pre = _snapshot() if (do_write_guard and name not in _WRITE_ON_SELFTEST) else None
        # 少数工具的开关不叫 `--selftest`（如 kb_lint_deep 走 kb_lint 的 --selftest-deep），
        # 用逐工具 argv 表表达，**不要**为了统一而给工具硬塞一个假开关。
        rc, out = _run([PY, path] + _SELFTEST_ARGV.get(name, ["--selftest"]))
        if rc is None:
            rec["selftest"] = "TIMEOUT"
        elif rc != 0:
            rec["selftest"] = "FAIL"
            rec["notes"].append("selftest: " + _last_line(out))
        else:
            # 只看**末行**判 FAIL：避免把夹具内部打印的 "FAIL"（反例演示）误判为工具失败
            tail = _last_line(out, 200).upper()
            if "FAIL" in tail and "PASS" not in tail:
                rec["selftest"] = "FAIL"
                rec["notes"].append("selftest: " + _last_line(out))
            else:
                rec["selftest"] = "PASS"
        if pre is not None:
            _guard(pre, since, "selftest", rec)
    else:
        rec["selftest"] = "NO-FLAG"

    # --- H CLI 健全性（--help 必须真的是帮助，不得执行 main） ---
    # 判定只看**输出是否像帮助**（usage/用法/options）；不强制 rc==0，
    # 因为自定义解析器在缺必填参数时可能返回非零（如 kb_where 返回 2）。
    since = _now_ns()
    pre = _snapshot() if do_write_guard else None
    rc, out = _run([PY, path, "--help"])
    low = (out or "").lower()
    is_help = ("usage" in low) or ("用法" in out) or ("options:" in low)
    if is_help:
        rec["help"] = "ok"
    else:
        rec["help"] = "NOT-HELP"
        rec["notes"].append("--help: " + _last_line(out))
    if pre is not None:
        _guard(pre, since, "--help", rec)
    return rec


def _tool_list(only=None):
    names = sorted(os.path.basename(p) for p in
                   glob.glob(os.path.join(TOOLS, "kb_*.py")) +
                   glob.glob(os.path.join(TOOLS, "qc_*.py")) +
                   glob.glob(os.path.join(TOOLS, "lit_*.py")) +
                   # 🔴 显式补 `kb.py`：它没有下划线，**天然逃过上面的 `kb_*.py` glob**，
                   #    于是这个「首选入口」成了全库唯一没有任何自动门禁的工具
                   #    （既不在本名单，也不在 kb_lint_deep 的 E 族里）。
                   glob.glob(os.path.join(TOOLS, "kb.py")))
    # 只排除**本检查器自身**（跑自己会递归）。kb_lib / kb_lint_deep 现在都在名单内：
    # 前者由 _EXCLUDED 说明理由并转由 kb_selftest.py 覆盖，后者本轮补了真 CLI。
    names = [n for n in names if n not in ("kb_toolcheck.py", "__init__.py")]
    if only:
        want = {x.strip() for x in only.split(",") if x.strip()}
        names = [n for n in names if n in want or n[:-3] in want]
    return names


def main():
    if "--selftest" in sys.argv:
        return run_selftest()
    if "--help" in sys.argv or "-h" in sys.argv:
        print(__doc__)
        return 0
    only = None
    if "--tools" in sys.argv:
        i = sys.argv.index("--tools")
        if i + 1 < len(sys.argv):
            only = sys.argv[i + 1]
    as_json = "--json" in sys.argv

    names = _tool_list(only)
    rows = []
    for n in names:
        rows.append(check_one(n, os.path.join(TOOLS, n)))

    if as_json:
        print(json.dumps(rows, ensure_ascii=False, indent=1))
        return 0

    print("=== 全库工具完整性 + 可行性检查 ===\n")
    print(f"{'tool':34s} {'comp':5s} {'selftest':9s} {'help':9s} {'write':7s}")
    problems = []
    exempt = 0
    ext_total = 0
    for r in rows:
        flag = ""
        if r["compile"] == "FAIL" or r["selftest"] == "FAIL" \
           or r["help"] == "NOT-HELP" or r["write_guard"] == "WRITES":
            flag = "  <<<"
            problems.append(r)
        w = r["write_guard"] or "-"
        if r["name"] in _WRITE_ON_SELFTEST and r["selftest"] not in (None, "NO-FLAG"):
            # 白名单内工具：其 selftest 本就会写盘，故写盘判据（S 段）被跳过，
            # 但 --help 段仍在监视。用 `*` 标出来，避免读表的人误以为「它也被全量监视了」。
            w = str(w) + "*"
            exempt += 1
        ext_total += len(r.get("external_writes") or [])
        print(f"{r['name']:34s} {str(r['compile']):5s} {str(r['selftest']):9s} "
              f"{str(r['help']):9s} {w:7s}{flag}")
    print()
    print(f"工具数: {len(rows)}  |  问题工具: {len(problems)}")
    print(f"监视范围: " + ", ".join(_WATCH_DIRS)
          + f"（排除 {'/'.join(_WATCH_EXCLUDE)}）")
    print(f"selftest 写盘豁免（_WRITE_ON_SELFTEST，标 *）: {exempt} 个"
          f"  |  --help 段仍全量监视")
    if ext_total:
        print(f"窗口外并发改动（不计入判定）: {ext_total} 个文件"
              f" —— 本库 Lead/subagent 会并发编辑 tools/ 与 wiki/，"
              f"数值偏高时本次写盘判据可信度下降")
    for r in problems:
        for nt in r["notes"]:
            print(f"  · {r['name']}: {nt}")
    return 0


# =================================================================== 自检

def run_selftest():
    """已知答案反算：正例（好工具）必须判 ok，反例（坏工具）必须被抓住。"""
    import tempfile
    global VAULT, _WATCH_DIRS, _WATCH_EXCLUDE
    ok = fail = 0

    def chk(label, cond):
        nonlocal ok, fail
        if cond:
            ok += 1
            print(f"  [PASS] {label}")
        else:
            fail += 1
            print(f"  [FAIL] {label}")

    d = tempfile.mkdtemp(prefix="kbtool_")

    def write(fn, content):
        p = os.path.join(d, fn)
        with open(p, "w", encoding="utf-8", newline="") as f:
            f.write(content)
        return p

    # 正例：有 --selftest（PASS）、--help 真帮助、不写盘
    good = write("good.py",
                 "import argparse\n"
                 "ap=argparse.ArgumentParser(description='demo')\n"
                 "ap.add_argument('--selftest',action='store_true')\n"
                 "a=ap.parse_args()\n"
                 "if a.selftest: print('SELFTEST PASSED'); raise SystemExit(0)\n")
    r = check_one("good.py", good)
    chk("正例 好工具 compile=ok", r["compile"] == "ok")
    chk("正例 好工具 selftest=PASS", r["selftest"] == "PASS")
    chk("正例 好工具 help=ok", r["help"] == "ok")
    chk("正例 好工具 无意外写盘", r["write_guard"] is None)

    # 反例1：--selftest 实跑报 FAIL
    bad_st = write("bad_st.py",
                   "import sys\n"
                   "if '--selftest' in sys.argv: print('SELFTEST FAIL'); raise SystemExit(1)\n"
                   "import argparse; argparse.ArgumentParser().parse_args()\n")
    r = check_one("bad_st.py", bad_st)
    chk("反例 selftest 报 FAIL 被抓住", r["selftest"] == "FAIL")

    # 反例2：--help 不提供帮助（无 argparse，直接执行 main）
    bad_help = write("bad_help.py",
                     "import sys\nprint('running main, wrote something')\n")
    r = check_one("bad_help.py", bad_help)
    chk("反例 --help 非帮助被抓住", r["help"] == "NOT-HELP")

    # 反例3：语法错误必须被 compile 抓到
    bad_compile = write("bad_compile.py", "def (:\n  pass\n")
    r = check_one("bad_compile.py", bad_compile)
    chk("反例 语法错误 compile=FAIL", r["compile"] == "FAIL")

    # 反例4：--help 路径写盘（须打开 do_write_guard，且监视目录临时指向临时夹）
    global _WATCH_DIRS, _WATCH_EXCLUDE
    old = _WATCH_DIRS
    _WATCH_DIRS = (d,)  # 绝对路径，直接监视临时目录
    writer = write("writer.py", "import os,sys\n"
                                "print('usage: writer.py')\n"
                                "open(os.path.join(os.path.dirname(__file__),'side.txt'),'w').write('x')\n"
                                "raise SystemExit(0)\n")
    r = check_one("writer.py", writer)
    _WATCH_DIRS = old
    chk("反例 --help 写盘被抓住", r["write_guard"] == "WRITES")

    # ---- 扩围后的新夹具（P2-8）--------------------------------------------
    # 旧监视集 = tools/ + wiki/.index/，而真实写盘脚本会写 wiki/index.md、
    # raw/notes/lit-watch/、.qc/ —— 这三处旧实现**完全看不见**。
    # 下面的夹具直接钉住「这三类位置现在会被抓住」与「wiki/.index 仍被排除」，
    # 而不是只断言 _WATCH_DIRS 这个字符串长什么样（字符串断言抓不到实现失效）。
    import shutil

    old_vault, old_wd, old_ex = VAULT, _WATCH_DIRS, _WATCH_EXCLUDE
    VAULT = d
    _WATCH_DIRS = ("wiki", "raw/notes/lit-watch", ".qc")
    _WATCH_EXCLUDE = ("wiki/.index",)
    # 写盘桩：--mode 决定写到哪个位置（含一个**被排除**的位置作反例）
    writer2 = write("writer2.py",
                    "import os,sys,argparse\n"
                    "ap=argparse.ArgumentParser(description='w')\n"
                    "ap.add_argument('--mode',default='wiki')\n"
                    "a=ap.parse_args()\n"
                    "print('usage: writer2.py')\n"
                    f"base={d!r}\n"
                    "tgt={'wiki':os.path.join(base,'wiki','sources','x.md'),\n"
                    "     'lit':os.path.join(base,'raw','notes','lit-watch','y.md'),\n"
                    "     'qc':os.path.join(base,'.qc','z.json'),\n"
                    "     'idx':os.path.join(base,'wiki','.index','meta.json')}[a.mode]\n"
                    "os.makedirs(os.path.dirname(tgt),exist_ok=True)\n"
                    "open(tgt,'w',encoding='utf-8').write('x')\n")

    def _clean():
        for sub in ("wiki", "raw", ".qc"):
            shutil.rmtree(os.path.join(d, sub), ignore_errors=True)

    def _guard_once(exe, mode):
        """按 check_one 里 selftest 段的真实顺序跑一次写盘判定。"""
        _clean()
        since = _now_ns()
        pre = _snapshot()
        _run([PY, exe, "--mode", mode])
        return _diff_snap(pre, _snapshot(), since=since)

    for mode, label in (("wiki", "wiki/sources/ 深层页面"),
                        ("lit", "raw/notes/lit-watch/"),
                        ("qc", ".qc/")):
        ch, ad, rm, ex = _guard_once(writer2, mode)
        chk(f"正例 写盘发生在 {label} 时被检出（改{len(ch)} 增{len(ad)}）",
            bool(ch or ad))

    ch, ad, rm, ex = _guard_once(writer2, "idx")
    chk(f"反例 wiki/.index/ 写盘被排除（改{len(ch)} 增{len(ad)}）"
        f"—— 派生数据会大面积 churn，判据会退化成「谁跑索引谁红」",
        not (ch or ad))
    # 正例：窗口**之前**就存在的差异必须归入 external，不得判红。
    # 这是并发环境（Lead + 多个 subagent 同时在改 tools/、wiki/）下的必要分流：
    # 没有它，一个外部编辑会让当时正在被检查的工具平白被判 WRITES。
    _clean()
    os.makedirs(os.path.join(d, "wiki"), exist_ok=True)
    stale = os.path.join(d, "wiki", "stale.md")
    with open(stale, "w", encoding="utf-8") as f:
        f.write("old content")
    old_t = time.time() - 3600
    os.utime(stale, (old_t, old_t))
    pre = _snapshot()
    with open(stale, "w", encoding="utf-8") as f:
        f.write("changed content!!")          # size 变了、mtime 被回写成 1 小时前
    os.utime(stale, (old_t, old_t))
    ch, ad, rm, ex = _diff_snap(pre, _snapshot(), since=_now_ns())
    chk(f"正例 旧 mtime 的差异归入 external 不判红（external={len(ex)} changed={len(ch)}）",
        "wiki/stale.md" in ex and "wiki/stale.md" not in ch)
    # 反例：mtime 落在窗口内的写入必须判红（否则分流会把真发现一起放过）
    # ⚠️ **必须显式设定 mtime**，不能靠"刚写完所以 mtime 比 since 新"：
    #    那依赖文件系统时间戳的分辨率，实测同一份自检跑 4 次会有 1 次 FAIL
    #    （changed=0 external=1）。**测时间边界的夹具就该自己控制时间。**
    pre = _snapshot()
    since = _now_ns()
    with open(stale, "w", encoding="utf-8") as f:
        f.write("fresh content!!!!")
    fresh_t = time.time() + 5                     # 明确落在窗口内
    os.utime(stale, (fresh_t, fresh_t))
    ch, ad, rm, ex = _diff_snap(pre, _snapshot(), since=since)
    chk(f"反例 窗口内的写入仍被判红（changed={len(ch)} external={len(ex)}）",
        "wiki/stale.md" in ch)
    # 正例：容差内的 mtime（比 since 早 0.5 s，但远新于 1 小时前的 stale）仍算窗口内。
    #   这条把 `_MTIME_GRACE_NS` 的**取舍**钉住：容差是吸收时间戳粒度用的，
    #   不是为了把真正的历史差异放进来（上面那条 1 小时前的差异仍判 external）。
    pre2 = _snapshot()
    since2 = _now_ns()
    grace_t = (since2 - 500_000_000) / 1e9        # since − 0.5 s，落在 1 s 容差内
    os.utime(stale, (grace_t, grace_t))
    ch2, ad2, rm2, ex2 = _diff_snap(pre2, _snapshot(), since=since2)
    chk(f"正例 容差内 mtime 不算 external（changed={len(ch2)} external={len(ex2)}）",
        "wiki/stale.md" in ch2 and "wiki/stale.md" not in ex2)
    VAULT, _WATCH_DIRS, _WATCH_EXCLUDE = old_vault, old_wd, old_ex

    print()
    print(f"SELFTEST {'PASSED' if fail == 0 else 'FAILED'}: {ok}/{ok+fail} cases correct")
    return 0 if fail == 0 else 1


if __name__ == "__main__":
    raise SystemExit(main())
